sourceCode.css:
body{margin: 0px; background: rgb(255, 255, 255); color: rgb(32, 40, 34); font: 16px / 1.7 sans-serif;}
header, footer{padding: 24px; border-bottom: 1px solid rgb(204, 204, 204);}
nav{display: flex; flex-wrap: wrap; gap: 24px;}
a{color: rgb(36, 83, 76);}
main{padding: 32px; max-width: 960px; margin: auto;}
p{max-width: 32em;}
h1{font-size: 32px; line-height: 1.3;}
section{padding: 24px 0px; border-top: 1px solid rgb(204, 204, 204);}
table{width: 100%; border-collapse: collapse;}
th, td{text-align: left; padding: 12px; border-bottom: 1px solid rgb(204, 204, 204);}
main, td{overflow-wrap: anywhere;}
